import{_ as t,o as a,c as d,a5 as r}from"./chunks/framework.DrDMl0tG.js";const u=JSON.parse('{"title":"Project Layout","description":"","frontmatter":{},"headers":[],"relativePath":"sections/ProjectLayout.md","filePath":"sections/ProjectLayout.md"}'),o={name:"sections/ProjectLayout.md"};function i(s,e,c,n,l,p){return a(),d("div",null,[...e[0]||(e[0]=[r(`<h1 id="project-layout" tabindex="-1">Project Layout <a class="header-anchor" href="#project-layout" aria-label="Permalink to &quot;Project Layout&quot;">​</a></h1><p><code>raisim2Lib</code> is the public package workspace. It downloads and uses binary RaiSim and rayrai packages, then provides examples, wrappers, resources, and documentation around those packages. It is not the RaiSim engine source tree, so engine-internal benchmark sources and implementation files are not available here. This page maps the directories users most often need while installing the package and building examples.</p><h2 id="public-workspace-directories" tabindex="-1">Public Workspace Directories <a class="header-anchor" href="#public-workspace-directories" aria-label="Permalink to &quot;Public Workspace Directories&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Path</th><th>Purpose</th></tr></thead><tbody><tr><td><code>raisim</code></td><td>Platform-specific binary RaiSim package with headers, libraries, and CMake config files. Downloaded by the first CMake configure (or <code>raisim_upgrade</code>); not tracked in Git.</td></tr><tr><td><code>rayrai</code></td><td>Platform-specific binary rayrai package with the renderer library, headers, and CMake config files. Downloaded together with <code>raisim</code>.</td></tr><tr><td><code>examples</code></td><td>C++ example sources and their CMake project. CMake target names include <code>primitive_grid</code> and <code>rayrai_tcp_viewer</code>.</td></tr><tr><td><code>examples/tools/debug</code></td><td>Optional manual regression and debug tools; see <a href="./DebugTools.html">Regression and Debug Tools</a>.</td></tr><tr><td><code>rsc</code></td><td>Runtime resources such as robot models, meshes, textures, USD/glTF assets, and example data.</td></tr><tr><td><code>raisimPy</code></td><td>Optional Python wrapper build for the binary RaiSim package.</td></tr><tr><td><code>raisimGymTorch</code></td><td>Reinforcement-learning package built against the binary RaiSim package.</td></tr><tr><td><code>docs</code></td><td>Documentation site: Markdown pages, the VitePress configuration and theme, and the scripts that generate the API reference.</td></tr><tr><td><code>thirdParty</code></td><td>Bundled third-party sources: Eigen3 (used by Windows builds) and nanobind (used by <code>raisimPy</code>).</td></tr><tr><td><code>scripts</code></td><td>Helper scripts: the Blender scene exporter (<code>export_blender_scene.py</code>) and the Linux desktop-launcher installer for <code>rayrai_tcp_viewer</code>.</td></tr><tr><td><code>raisim_env.*</code>, <code>raisim_upgrade.*</code></td><td>Environment scripts that add the package library directories to the library search path (<code>.sh</code>, <code>.bat</code>, <code>.ps1</code>) and scripts that download a release package into <code>raisim</code> and <code>rayrai</code> (<code>.sh</code>, <code>.ps1</code>).</td></tr></tbody></table><h2 id="build-directories" tabindex="-1">Build Directories <a class="header-anchor" href="#build-directories" aria-label="Permalink to &quot;Build Directories&quot;">​</a></h2><p>Build directories are generated locally and are not part of the repository. The docs use these names for clarity:</p><table tabindex="0"><thead><tr><th>Build directory</th><th>Typical use</th></tr></thead><tbody><tr><td><code>build</code></td><td>Default local build for examples and optional wrappers.</td></tr><tr><td><code>build-examples</code></td><td>Top-level build with examples enabled; the example commands in these docs use it.</td></tr><tr><td><code>build-debug</code></td><td>Debug build for local debugging.</td></tr><tr><td><code>build-docs</code></td><td>CMake-driven docs build.</td></tr></tbody></table><p>On Linux and macOS, a top-level build places example executables, together with a copy of <code>rsc</code>, under the <code>examples</code> subdirectory of the build tree. The install target does not copy these source-built examples, and the release package does not ship a separate prebuilt TCP viewer. For example:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build-examples/examples/primitive_grid</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build-examples/examples/rayrai_tcp_viewer</span></span></code></pre></div><p>On Windows, CMake places the example executables under <code>&lt;build-dir&gt;/bin</code>, together with a copy of <code>rsc</code> and the runtime DLLs.</p><p>The package example tree documented under <a href="./Examples.html">Examples</a> contains grouped source directories such as <code>src/server</code>, <code>src/rayrai</code>, <code>src/worlds</code>, <code>src/xml</code>, and <code>src/benchmark</code>. Target names, not source directory names, are the stable user-facing interface.</p><h2 id="installed-package-layout" tabindex="-1">Installed Package Layout <a class="header-anchor" href="#installed-package-layout" aria-label="Permalink to &quot;Installed Package Layout&quot;">​</a></h2><p>The unpacked release contains separate package prefixes for RaiSim and rayrai:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;raisim2Lib&gt;/raisim</span></span>
<span class="line"><span>&lt;raisim2Lib&gt;/rayrai</span></span></code></pre></div><p>Downstream projects use <code>CMAKE_PREFIX_PATH</code> to find these installed packages. See <a href="./Installation.html">Installation</a> for environment setup and activation.</p><h2 id="where-to-add-new-things" tabindex="-1">Where To Add New Things <a class="header-anchor" href="#where-to-add-new-things" aria-label="Permalink to &quot;Where To Add New Things&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Change</th><th>Usual location</th></tr></thead><tbody><tr><td>New user-facing C++ example</td><td><code>examples/src</code> plus a target registration in <code>examples/CMakeLists.txt</code>.</td></tr><tr><td>New example resource</td><td><code>rsc</code>. Put example-only resources under a relevant subdirectory there.</td></tr><tr><td>New Python wrapper behavior</td><td><code>raisimPy</code>.</td></tr><tr><td>New RL package behavior</td><td><code>raisimGymTorch</code>.</td></tr><tr><td>New docs page</td><td>A Markdown file in <code>docs/sections</code> and an entry in <code>docs/.vitepress/sidebar.mts</code>.</td></tr></tbody></table><p>Keep examples focused on demonstrating the public binary-package APIs.</p>`,18)])])}const m=t(o,[["render",i]]);export{u as __pageData,m as default};
